script:
test('six payments within nine minutes alert at the sixth payment time', function () {
  assert.deepEqual(code.checkCardPayments({
    paymentTimes: [
      '2024-06-15T10:00:00Z',
      '2024-06-15T10:02:00Z',
      '2024-06-15T10:04:00Z',
      '2024-06-15T10:06:00Z',
      '2024-06-15T10:08:00Z',
      '2024-06-15T10:09:00Z'
    ]
  }), { alert: true, alertTime: '2024-06-15T10:09:00Z' });
});

test('payments exactly ten minutes apart raise no alert', function () {
  assert.deepEqual(code.checkCardPayments({
    paymentTimes: [
      '2024-06-15T10:00:00Z',
      '2024-06-15T10:02:00Z',
      '2024-06-15T10:04:00Z',
      '2024-06-15T10:06:00Z',
      '2024-06-15T10:08:00Z',
      '2024-06-15T10:10:00Z'
    ]
  }), { alert: false, alertTime: null });
});

test('exactly five payments raise no alert', function () {
  assert.deepEqual(code.checkCardPayments({
    paymentTimes: [
      '2024-06-15T10:00:00Z',
      '2024-06-15T10:02:00Z',
      '2024-06-15T10:04:00Z',
      '2024-06-15T10:06:00Z',
      '2024-06-15T10:08:00Z'
    ]
  }), { alert: false, alertTime: null });
});

test('four payments raise no alert', function () {
  assert.deepEqual(code.checkCardPayments({
    paymentTimes: [
      '2024-06-15T10:00:00Z',
      '2024-06-15T10:02:00Z',
      '2024-06-15T10:04:00Z',
      '2024-06-15T10:06:00Z'
    ]
  }), { alert: false, alertTime: null });
});

test('a sixth payment one second under ten minutes raises an alert', function () {
  assert.deepEqual(code.checkCardPayments({
    paymentTimes: [
      '2024-06-15T10:00:00Z',
      '2024-06-15T10:02:00Z',
      '2024-06-15T10:04:00Z',
      '2024-06-15T10:06:00Z',
      '2024-06-15T10:08:00Z',
      '2024-06-15T10:09:59Z'
    ]
  }), { alert: true, alertTime: '2024-06-15T10:09:59Z' });
});

test('a sixth payment one second over ten minutes raises no alert', function () {
  assert.deepEqual(code.checkCardPayments({
    paymentTimes: [
      '2024-06-15T10:00:00Z',
      '2024-06-15T10:02:00Z',
      '2024-06-15T10:04:00Z',
      '2024-06-15T10:06:00Z',
      '2024-06-15T10:08:00Z',
      '2024-06-15T10:10:01Z'
    ]
  }), { alert: false, alertTime: null });
});

test('an empty payment list raises no alert', function () {
  assert.deepEqual(code.checkCardPayments({
    paymentTimes: []
  }), { alert: false, alertTime: null });
});

test('a single payment raises no alert', function () {
  assert.deepEqual(code.checkCardPayments({
    paymentTimes: ['2024-06-15T10:00:00Z']
  }), { alert: false, alertTime: null });
});

test('excluding a payment exactly ten minutes earlier leaves five and raises no alert', function () {
  assert.deepEqual(code.checkCardPayments({
    paymentTimes: [
      '2024-06-15T09:50:00Z',
      '2024-06-15T10:00:00Z',
      '2024-06-15T10:10:00Z',
      '2024-06-15T10:12:00Z',
      '2024-06-15T10:14:00Z',
      '2024-06-15T10:16:00Z',
      '2024-06-15T10:18:00Z',
      '2024-06-15T10:20:00Z'
    ]
  }), { alert: false, alertTime: null });
});

test('the alert time is the middle payment that first reaches six in a window', function () {
  assert.deepEqual(code.checkCardPayments({
    paymentTimes: [
      '2024-06-15T10:00:00Z',
      '2024-06-15T10:01:00Z',
      '2024-06-15T10:02:00Z',
      '2024-06-15T10:03:00Z',
      '2024-06-15T10:04:00Z',
      '2024-06-15T10:05:00Z',
      '2024-06-15T10:20:00Z'
    ]
  }), { alert: true, alertTime: '2024-06-15T10:05:00Z' });
});

test('the alert time is the last payment when an earlier payment is outside the window', function () {
  assert.deepEqual(code.checkCardPayments({
    paymentTimes: [
      '2024-06-15T09:00:00Z',
      '2024-06-15T10:00:00Z',
      '2024-06-15T10:02:00Z',
      '2024-06-15T10:04:00Z',
      '2024-06-15T10:06:00Z',
      '2024-06-15T10:08:00Z',
      '2024-06-15T10:09:00Z'
    ]
  }), { alert: true, alertTime: '2024-06-15T10:09:00Z' });
});

test('six payments crossing from December 31 to January 1 raise an alert', function () {
  assert.deepEqual(code.checkCardPayments({
    paymentTimes: [
      '2023-12-31T23:56:00Z',
      '2023-12-31T23:57:00Z',
      '2023-12-31T23:58:00Z',
      '2023-12-31T23:59:00Z',
      '2024-01-01T00:00:00Z',
      '2024-01-01T00:01:00Z'
    ]
  }), { alert: true, alertTime: '2024-01-01T00:01:00Z' });
});

test('six payments crossing from January 31 to February 1 raise an alert', function () {
  assert.deepEqual(code.checkCardPayments({
    paymentTimes: [
      '2024-01-31T23:56:00Z',
      '2024-01-31T23:57:00Z',
      '2024-01-31T23:58:00Z',
      '2024-01-31T23:59:00Z',
      '2024-02-01T00:00:00Z',
      '2024-02-01T00:01:00Z'
    ]
  }), { alert: true, alertTime: '2024-02-01T00:01:00Z' });
});

test('six payments on leap day alert at the sixth payment time', function () {
  assert.deepEqual(code.checkCardPayments({
    paymentTimes: [
      '2024-02-29T10:00:00Z',
      '2024-02-29T10:02:00Z',
      '2024-02-29T10:04:00Z',
      '2024-02-29T10:06:00Z',
      '2024-02-29T10:08:00Z',
      '2024-02-29T10:09:00Z'
    ]
  }), { alert: true, alertTime: '2024-02-29T10:09:00Z' });
});

test('payments split across leap day raise no alert', function () {
  assert.deepEqual(code.checkCardPayments({
    paymentTimes: [
      '2024-02-28T23:56:00Z',
      '2024-02-28T23:57:00Z',
      '2024-02-28T23:58:00Z',
      '2024-02-28T23:59:00Z',
      '2024-03-01T00:00:00Z',
      '2024-03-01T00:01:00Z'
    ]
  }), { alert: false, alertTime: null });
});

test('a later window that keeps a payment one second inside ten minutes alerts at that later time', function () {
  assert.deepEqual(code.checkCardPayments({
    paymentTimes: [
      '2024-06-15T09:40:00Z',
      '2024-06-15T09:50:00Z',
      '2024-06-15T10:00:00Z',
      '2024-06-15T10:10:01Z',
      '2024-06-15T10:12:00Z',
      '2024-06-15T10:14:00Z',
      '2024-06-15T10:16:00Z',
      '2024-06-15T10:18:00Z',
      '2024-06-15T10:20:00Z'
    ]
  }), { alert: true, alertTime: '2024-06-15T10:20:00Z' });
});
